from lib import *
S = SS('w40')
steps = [
    step("netlab 给回环加 150 ms 单向延迟(往返 300 ms)后,每一步都慢到 netstat 能抓到。场景 1:握手、数据、客户端先 close、服务端晚 1 秒才 close。客户端的状态依次是 SYN_SENT(111 ms)→ ESTABLISHED(411 ms)→ FIN_WAIT_1(1075 ms)→ FIN_WAIT_2(1378 ms)→ TIME_WAIT(2249 ms);服务端是 SYN_RCVD(263 ms)→ ESTABLISHED(580 ms)→ CLOSE_WAIT(1222 ms)→ LAST_ACK(2110 ms)→ 消失(2381 ms);监听套接字一直是 LISTEN。客户端在 FIN_WAIT_2 停了约 870 ms(1378 到 2249 ms),正是服务端迟迟不 close、停在 CLOSE_WAIT 的那段时间。服务端 LAST_ACK 之后连接直接消失,没有 TIME_WAIT——TIME_WAIT 留给主动关闭的一方。 场景 2:客户端 connect 之后立刻 close,服务端也立刻 close。两端状态完全对称:SYN_SENT / SYN_RCVD → ESTABLISHED(客户端 405 ms)→ 两端同时 FIN_WAIT_1(576 ms)→ 两端同时 CLOSING(730 ms)→ 两端同时 TIME_WAIT(871 ms)。因为两个 FIN 在 300 ms 的往返里交叉,谁也没有先收到对 FIN 的 ACK,而是先收到对方的 FIN,所以进入 CLOSING。场景 3(两端用屏障同时 close)结果相同:FIN_WAIT_1(1081 ms)→ CLOSING(1241 ms)→ TIME_WAIT(1386 ms)。同时关闭时两端都留下 TIME_WAIT。", t=tl(S(1)), mark=lidx(S(1), '客户端:SYN_SENT(111 ms)', '服务端:SYN_RCVD(263 ms)', '客户端:SYN_SENT(118 ms)', '一端:SYN_SENT(135 ms)'), done=lidx(S(1), '监听套接字', '这个场景里见到的状态', '服务端:SYN_RCVD(254 ms)', '另一端:SYN_RCVD(254 ms)'), b=bars([['客户端 · ESTABLISHED 时刻', 411, '411 ms'], ['客户端 · FIN_WAIT_2 时刻', 1378, '1378 ms'], ['客户端 · TIME_WAIT 时刻', 2249, '2249 ms'], ['服务端 · LAST_ACK 时刻', 2110, '2110 ms'], ['服务端 · 连接消失', 2381, '2381 ms']], 2381, mark=[1, 3], done=[0, 2, 4]), kv=KV([['客户端(主动关闭)', 'SYN_SENT → ESTABLISHED → FIN_WAIT_1 → FIN_WAIT_2 → TIME_WAIT'], ['服务端(被动关闭)', 'SYN_RCVD → ESTABLISHED → CLOSE_WAIT → LAST_ACK → 消失'], ['TIME_WAIT', '只留给主动关闭的一方']], ['TIME_WAIT'])),
    step("状态总表:11 个状态各自的触发条件,在本机 netstat 里全部见到了——LISTEN、SYN_SENT、SYN_RCVD、ESTABLISHED、FIN_WAIT_1、FIN_WAIT_2、CLOSE_WAIT、CLOSING、LAST_ACK、TIME_WAIT 十个,加上 CLOSED(netstat 里没有这一行)共 11 / 11。LISTEN:服务端 listen() 之后;SYN_SENT:客户端发出 SYN 等 SYN-ACK;SYN_RCVD:服务端收到 SYN、发出 SYN-ACK、等第三个 ACK;ESTABLISHED:握手完成;FIN_WAIT_1:主动关闭方发出 FIN 等 ACK;FIN_WAIT_2:FIN 已被 ACK、等对方的 FIN;CLOSE_WAIT:被动关闭方收到 FIN 并已 ACK,等本端应用 close();CLOSING:同时关闭,发出 FIN 后先收到对方的 FIN;LAST_ACK:被动关闭方发出 FIN 等最后的 ACK;TIME_WAIT:主动关闭方收到对方的 FIN 并回了 ACK,等 2MSL。", t=tl(S(2)), mark=lidx(S(2), 'CLOSING     ', 'LAST_ACK    ', 'TIME_WAIT   ', 'CLOSE_WAIT  '), done=lidx(S(2), 'CLOSED      ', 'LISTEN      ', 'SYN_SENT    ', 'SYN_RCVD    ', 'ESTABLISHED ', 'FIN_WAIT_1  ', 'FIN_WAIT_2  ', '三个场景里'), b=bars([['抓到的状态', 10, '10'], ['CLOSED(没有这一行)', 1, '1'], ['合计', 11, '11 / 11']], 11, mark=[2], done=[0, 1]), kv=KV([['握手', 'LISTEN · SYN_SENT · SYN_RCVD · ESTABLISHED'], ['主动关闭', 'FIN_WAIT_1 · FIN_WAIT_2 · TIME_WAIT'], ['被动关闭', 'CLOSE_WAIT · LAST_ACK'], ['同时关闭', 'CLOSING']], ['同时关闭'])),
    step("SYN_SENT 与 SYN_RCVD:非阻塞 connect 到一个丢弃 SYN 的公网地址,0.5 秒后 netstat 看到 SYN_SENT。场景 4:非阻塞 connect,服务端始终不 accept:客户端 SYN_SENT(127 ms)→ ESTABLISHED(432 ms),服务端 SYN_RCVD(279 ms)→ ESTABLISHED(579 ms)——服务端的 SYN_RCVD 持续了约 300 ms,正好是回 SYN-ACK 到收到第三个 ACK 的一个往返,而服务端应用从头到尾没调用 accept();握手是内核完成的,没被 accept 的连接排在全连接队列里(下面 backlog 一篇展开)。之后客户端 close,服务端停在 CLOSE_WAIT(994 ms),客户端在 FIN_WAIT_2(1139 ms)。", t=tl(S(3)), mark=lidx(S(3), '非阻塞 connect 到一个丢弃', '客户端:SYN_SENT(127 ms)', '服务端:SYN_RCVD(279 ms)'), done=lidx(S(3), '服务端内核在回了'), b=bars([['服务端 SYN_RCVD 持续', 300, '约 300 ms'], ['往返', 300, '300 ms']], 300, mark=[0], done=[1]), kv=KV([['SYN_SENT', '客户端发出 SYN 后、收到 SYN-ACK 前'], ['SYN_RCVD', '服务端回 SYN-ACK 后、收到第三个 ACK 前'], ['accept()', '不影响状态:握手由内核完成']], ['accept()'])),
]
A = mkartw('w40', 40, '网络协议,TCP,状态机,netstat,FIN_WAIT,CLOSE_WAIT,TIME_WAIT,真实验证,动画演示',
    '用 netlab 把回环的握手和挥手拖慢到 netstat 能抓到,逐个观察 TCP 的 11 个状态;客户端先关的路径(FIN_WAIT_1/2 → TIME_WAIT)、服务端(CLOSE_WAIT → LAST_ACK → 消失)、同时关闭(CLOSING)、握手期的 SYN_RCVD。',
    'TCP 状态机的 11 个状态,在 netstat 里到底什么时候出现?CLOSE_WAIT 为什么会堆积,TIME_WAIT 留给谁?这篇给回环加延迟,每 20 ms 查一次 netstat,把一次连接从诞生到消失的每个状态和时刻记下来。',
    [('11 / 11', '本机 netstat 里观察到的 TCP 状态数(10 个出现的状态加没有这一行的 CLOSED)'), ('约 300 ms', '服务端停在 SYN_RCVD 的时间:回 SYN-ACK 到收到第三个 ACK 的一个往返'), ('2249 ms', '客户端先 close 的场景里,客户端进入 TIME_WAIT 的时刻;服务端 LAST_ACK 之后直接消失')],
    [('握手的状态', '<p>客户端 SYN_SENT → ESTABLISHED;服务端 SYN_RCVD → ESTABLISHED,其中 SYN_RCVD 持续一个往返。服务端有没有 accept() 不影响状态。</p>'),
     ('11 个状态', '<p>LISTEN、SYN_SENT、SYN_RCVD、ESTABLISHED、FIN_WAIT_1、FIN_WAIT_2、CLOSE_WAIT、CLOSING、LAST_ACK、TIME_WAIT 十个在 netstat 里都能抓到,CLOSED 就是没有这一行。</p>'),
     ('主动关闭、被动关闭与同时关闭', '<p>主动方 FIN_WAIT_1 → FIN_WAIT_2 → TIME_WAIT;被动方 CLOSE_WAIT(等本端应用 close)→ LAST_ACK → 消失;同时关闭两端 FIN_WAIT_1 → CLOSING → TIME_WAIT。大量 CLOSE_WAIT 说明应用没有及时 close()。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上,延迟由 netlab 注入(单向 150 ms);状态靠每 20 ms 通过 netstat -an -p tcp 取一次快照,记录的是第一次看到的时刻,精度约几十毫秒;netstat 里没有的连接就是 CLOSED',
     '没有验证:真实网络上的同样路径;状态之间的超时(FIN_WAIT_2 的超时、TIME_WAIT 的 2MSL 时长,见下一篇);大量 CLOSE_WAIT / SYN_RCVD 堆积的诊断;其它系统的 netstat 对状态的命名差异'],
    'TCP 状态机')
